@startuml

class Well {
  + code : string
  + pollutionRate() : double
}

abstract class Company {
  + taxCode : string
  + numberOfEmployees() : int
}

interface OilExtraction {
  + extractCrudeOil(quantity : double) : void
}

class OnshoreWell extends Well implements OilExtraction {
  + surfaceExtension : float
  + calculatePollutionRate() : double
}

class OffshoreWell extends Well implements OilExtraction {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
  + calculatePollutionRate() : double
}

class Area {
  + code : string
  + environmentalImportance : int
}

Company "1..*" -- "*" Well : extractsCrudeOilFrom
OnshoreWell "1" -- "0..*" Company : extractedBy
OffshoreWell "1" -- "0..*" Company : extractedBy
OffshoreWell "1" -- "0..1" Area : locatedIn

@enduml

